from collections import deque
def solve(g,wall=4,fill=3,bg=1):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg: q.append((i,j)); seen[i][j]=True
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg: q.append((i,j)); seen[i][j]=True
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and not seen[a][b] and g[a][b]==bg:
                seen[a][b]=True; q.append((a,b))
    return [[fill if g[i][j]==bg and not seen[i][j] else g[i][j] for j in range(w)] for i in range(h)]
