def enclosed(g,wall=4,bg=1):
    h,w=len(g),len(g[0])
    def isw(i,j): return i<0 or j<0 or i>=h or j>=w or g[i][j]==wall
    seen=set(); q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg: q.append((i,j)); seen.add((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg: q.append((i,j)); seen.add((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and g[a][b]==bg and (a,b) not in seen:
                # corner rule: blocked if the two cells adjacent to the corner are walls
                if di and dj: pass
                if di!=0:
                    # vertical move; blocked if walls at (i,j+1?) actually corner cells (i, j) side
                    if isw(i, j+(1 if dj else 0)) : pass
                # implement: moving (i,j)->(a,b); corner cells are (i,b) and (a,j); blocked if both walls
                if isw(i,b) and isw(a,j):
                    continue
                seen.add((a,b)); q.append((a,b))
    return {(i,j) for i in range(h) for j in range(w) if g[i][j]==bg and (i,j) not in seen}
